<?php
namespace App\Http\Controllers;
use App\Models\HrAttendanceException;use App\Models\HrCertification;use App\Models\HrEmployeeRequest;use App\Models\HrOffboardingCase;use App\Models\HrOnboardingCase;use App\Models\HrProbationReview;
class HrWorklistController extends AccountBaseController {public function index(){abort_403(!in_array(user()->permission('edit_employees'),['all','branch'],true));$company=user()->company_id;$this->items=collect();foreach([['Onboarding',HrOnboardingCase::where('company_id',$company)->where('status','open')->count()],['Offboarding',HrOffboardingCase::where('company_id',$company)->where('status','open')->count()],['Attendance exceptions',HrAttendanceException::where('company_id',$company)->where('status','pending')->count()],['Employee requests',HrEmployeeRequest::where('company_id',$company)->where('status','pending')->count()],['Probation reviews',HrProbationReview::where('company_id',$company)->where('status','pending')->count()],['Expired certifications',HrCertification::where('company_id',$company)->whereDate('expires_at','<',today())->count()]] as [$label,$count])$this->items->push(compact('label','count'));return view('hr-worklist.index',$this->data);}}
